final_design:
module ModuleA (
    input  logic x,
    input  logic y,
    output logic z
);
    assign z = (x ^ y) & x;
endmodule

module ModuleB (
    input  logic x,
    input  logic y,
    output logic z
);
    assign z = ~(x ^ y);
endmodule

module TopModule (
    input  logic x,
    input  logic y,
    output logic z
);
    logic a1_out, b1_out;
    logic a2_out, b2_out;
    logic or_out, and_out;

    ModuleA u_a1 (.x(x), .y(y), .z(a1_out));
    ModuleB u_b1 (.x(x), .y(y), .z(b1_out));

    ModuleA u_a2 (.x(x), .y(y), .z(a2_out));
    ModuleB u_b2 (.x(x), .y(y), .z(b2_out));

    assign or_out  = a1_out | b1_out;
    assign and_out = a2_out & b2_out;
    assign z       = or_out ^ and_out;

endmodule

